"""Minimal tessaro-feeds stub providing PinStore and fingerprint utilities."""

import hashlib
import json
import os


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 hex fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Simple certificate pin store that reads from a JSON config file."""

    _default_path = os.path.join(os.path.dirname(__file__), "pins.json")

    def __init__(self, path=None):
        if path is None:
            path = self._default_path
        self.path = path
        if os.path.exists(path):
            with open(path) as f:
                self._pins = json.load(f)
        else:
            self._pins = {}

    @classmethod
    def load(cls):
        """Load the pin store from the default location or TESSARO_PINS env var."""
        path = os.environ.get("TESSARO_PINS")
        return cls(path=path)

    def matches(self, host: str, fp: str) -> bool:
        """Return True if the fingerprint matches the pinned value for host."""
        return self._pins.get(host) == fp
